import re


def _clean_words(text, stop_words):
    words = re.findall(r"[A-Za-z']+", text.lower())
    stop = set(w.lower() for w in stop_words)
    return {w for w in words if w not in stop}


def text_similarity(path1, path2, stop_words):
    with open(path1, encoding="utf-8") as f:
        words1 = _clean_words(f.read(), stop_words)
    with open(path2, encoding="utf-8") as f:
        words2 = _clean_words(f.read(), stop_words)
    return round(len(words1 & words2) / len(words1 | words2), 4)
